@@ -17,8 +17,11 @@ package s2
 import (
 	"bufio"
 	"encoding/binary"
+	"errors"
 	"io"
 	"math"
+
+	"github.com/golang/geo/r3"
 )

 const (
@@ -120,6 +123,12 @@ func (e *encoder) writeFloat64(x float64) {
 	e.err = binary.Write(e.w, binary.LittleEndian, x)
 }

+func (e *encoder) writePoint(p Point) {
+	e.writeFloat64(p.X)
+	e.writeFloat64(p.Y)
+	e.writeFloat64(p.Z)
+}
+
 type byteReader interface {
 	io.Reader
 	io.ByteReader
@@ -203,3 +212,37 @@ func (d *decoder) readUvarint() (x uint64) {
 	x, d.err = binary.ReadUvarint(d.r)
 	return
 }
+
+func (d *decoder) readInt32() (x int32) {
+	if d.err != nil {
+		return
+	}
+	d.err = binary.Read(d.r, binary.LittleEndian, &x)
+	return
+}
+
+func (d *decoder) readInt64() (x int64) {
+	if d.err != nil {
+		return
+	}
+	d.err = binary.Read(d.r, binary.LittleEndian, &x)
+	return
+}
+
+func (d *decoder) readPoint() Point {
+	if d.err != nil {
+		return Point{}
+	}
+	x := d.readFloat64()
+	y := d.readFloat64()
+	z := d.readFloat64()
+	if d.err != nil {
+		return Point{}
+	}
+	if math.IsNaN(x) || math.IsNaN(y) || math.IsNaN(z) ||
+		math.IsInf(x, 0) || math.IsInf(y, 0) || math.IsInf(z, 0) {
+		d.err = errors.New("point coordinates must be finite numbers")
+		return Point{}
+	}
+	return Point{r3.Vector{X: x, Y: y, Z: z}}
+}
