+	"fmt"
+	"io"
+)
+
 // Shape interface enforcement
 var _ Shape = (*LaxPolygon)(nil)

@@ -220,5 +225,85 @@ func (p *LaxPolygon) ChainPosition(e int) ChainPosition {
 	return ChainPosition{p.cumulativeVertices[nextLoop] - p.cumulativeVertices[1], e - p.cumulativeVertices[nextLoop-1]}
 }

+// Encode encodes the LaxPolygon.
+func (p *LaxPolygon) Encode(w io.Writer) error {
+	e := &encoder{w: w}
+	p.encode(e)
+	return e.err
+}
+
+func (p *LaxPolygon) encode(e *encoder) {
+	e.writeInt8(encodingVersion)
+	e.writeUint32(uint32(p.numLoops))
+	for i := 0; i < p.numLoops; i++ {
+		e.writeUint32(uint32(p.numLoopVertices(i)))
+	}
+	totalVerts := p.numVertices()
+	for i := 0; i < totalVerts; i++ {
+		e.writePoint(p.vertices[i])
+	}
+}
+
+// Decode decodes the LaxPolygon.
+func (p *LaxPolygon) Decode(r io.Reader) error {
+	d := &decoder{r: asByteReader(r)}
+	p.decode(d)
+	return d.err
+}
+
+func (p *LaxPolygon) decode(d *decoder) {
+	version := d.readInt8()
+	if d.err != nil {
+		return
+	}
+	if version != encodingVersion {
+		d.err = fmt.Errorf("cannot decode LaxPolygon version %d; my version: %d", version, encodingVersion)
+		return
+	}
+	numLoops := d.readUint32()
+	if d.err != nil {
+		return
+	}
+	if numLoops > maxEncodedLoops {
+		d.err = fmt.Errorf("too many loops (%d; max is %d)", numLoops, maxEncodedLoops)
+		return
+	}
+
+	loopSizes := make([]int, 0, min(int(numLoops), 1024))
+	var totalVerts int
+	for range numLoops {
+		sz := d.readUint32()
+		if d.err != nil {
+			return
+		}
+		if sz > maxEncodedVertices {
+			d.err = fmt.Errorf("too many vertices in loop (%d; max is %d)", sz, maxEncodedVertices)
+			return
+		}
+		totalVerts += int(sz)
+		if totalVerts > maxEncodedVertices {
+			d.err = fmt.Errorf("too many total vertices (%d; max is %d)", totalVerts, maxEncodedVertices)
+			return
+		}
+		loopSizes = append(loopSizes, int(sz))
+	}
+
+	loops := make([][]Point, numLoops)
+	for i, sz := range loopSizes {
+		loop := make([]Point, 0, min(sz, 1024))
+		for range sz {
+			pt := d.readPoint()
+			if d.err != nil {
+				return
+			}
+			loop = append(loop, pt)
+		}
+		loops[i] = loop
+	}
+
+	lp := LaxPolygonFromPoints(loops)
+	*p = *lp
+}
+
